export const HELP_TOPICS=[
 ['start','How do I play?','Start with Balanced build, open Launch readiness, then authorize launch. Map in sunlight. When an event pauses the game, read the choices and choose a response. Return at least 520 useful science units within 240 campaign minutes, with battery remaining.','খেলা শুরু: Balanced build নিন, Launch readiness দেখে launch করুন। Map in sunlight চালান। বিপদ এলে একটি সিদ্ধান্ত নিন। ২৪০ মিনিটে অন্তত ৫২০ science পৃথিবীতে ফেরত পাঠাতে হবে।','play start beginner tutorial khelbo kheli shuru শুরু খেলবো খেলব কিভাবে'],
 ['goal','What counts as success?','Return at least 520 of the 650 target science units and finish with battery above zero. Hardware, launch and operations must fit the 150-credit budget. Science sitting in storage does not count.','লক্ষ্য: ৬৫০-এর মধ্যে অন্তত ৫২০ science পৃথিবীতে পাঠানো, ব্যাটারি সচল রাখা এবং ১৫০ credit-এর মধ্যে design করা। শুধু জমা ডেটায় score হয় না।','goal win success score objective target jitbo জিত লক্ষ্য স্কোর'],
 ['battery','Why is my battery dropping?','Solar panels make electricity in sunlight. The battery carries the spacecraft through shadow. W measures power; Wh measures stored energy. Safe mode begins at 15% and stops science and transmission; it recovers above 40%. Zero energy ends this game mission. Conserve energy pauses both collection and transmission.','রোদে solar panel বিদ্যুৎ দেয়, ছায়ায় battery খরচ হয়। W হলো বিদ্যুতের হার, Wh হলো জমা শক্তি। ১৫% হলে safe mode, ৪০%-এর বেশি হলে recovery; শূন্য হলে মিশন শেষ। Conserve energy দিলে ছবি তোলা ও ডেটা পাঠানো থামে।','battery energy power solar eclipse shadow safe mode wh watt ব্যাটারি বিদ্যুৎ শক্তি ছায়া'],
 ['data','Why is my recorder full?','The instrument collects data into the recorder. Contact windows let the antenna send it to Earth. Full storage discards NEW observations, not older ones. Return priority pauses collection and resumes it after the recorder falls below 25%. A bigger recorder does not make the link faster.','Camera ডেটা জমায়, antenna contact window-তে পৃথিবীতে পাঠায়। Storage পূর্ণ হলে নতুন ডেটা নষ্ট হয়। Return priority দিলে সংগ্রহ থামে, storage ২৫%-এর নিচে নামলে আবার শুরু হয়।','data storage recorder full overflow backlog memory downlink ডেটা স্টোরেজ ভরে'],
 ['commands','Which command should I use?','Map in sunlight is the easiest starting schedule. Map through shadow increases observations and battery drain. Conserve energy pauses collection AND transmission. Return priority pauses collection but transmits during contact. A manually selected Conserve command stays active until you change it.','শুরুতে Map in sunlight নিন। Map through shadow-তে battery বেশি লাগে। Conserve energy দুটো কাজই থামায়। Return priority জমা ডেটা আগে পাঠায়। নিজে Conserve দিলে আবার নিজেকেই command বদলাতে হবে।','command controls schedule operate buttons mapping aggressive coast বোতাম চালাব কমান্ড'],
 ['crisis','What should I do in a crisis?','The game pauses for your decision. Every response lists its consequence. Disabled choices exceed your spacecraft capabilities. Energy recovery can pause activities; recorder recovery can pause collection; link boost needs enough solar power; capture needs enough maneuver capability.','বিপদে গেম নিজে pause হয়। প্রতিটি option-এর ফল লেখা আছে। Disabled মানে আপনার spacecraft সেই কাজ করতে পারবে না। নিচের সিদ্ধান্ত বেছে তারপর Resume দিন।','crisis recover emergency warning problem decision বিপদ সমস্যা রিকভারি'],
 ['fuel','How much fuel do I need?','Fuel adds maneuver capability but also launch mass. The game asks for 650 m/s capture/correction plus 100 m/s reserve. Δv is the possible change in velocity, not your current speed. The rocket equation uses wet mass, dry mass and engine specific impulse.','Fuel বাড়লে চালনা করার ক্ষমতা বাড়ে, ওজনও বাড়ে। Capture-এর জন্য ৬৫০ m/s এবং reserve ১০০ m/s লাগে। Δv হলো গতি বদলানোর ক্ষমতা, বর্তমান গতি নয়।','fuel propellant propulsion thruster isp delta dv Δv capture জ্বালানি ফুয়েল'],
 ['mass','Why is launch blocked?','Launch is blocked when wet mass exceeds launcher capacity, cost exceeds 150 credits, or the recorder is incompatible with the bus. Warnings are permitted but need a plan. Try lighter hardware, less fuel, a compatible recorder or a larger launcher, then recheck all margins.','ওজন সীমার বেশি, খরচ ১৫০-এর বেশি বা bus–storage না মিললে launch বন্ধ থাকে। হালকা part, কম fuel বা উপযুক্ত launcher নিন; তারপর সব margin আবার দেখুন।','mass weight launch blocked budget cost credit expensive fail readiness ওজন বাজেট খরচ লঞ্চ'],
 ['orbit','What do altitude and inclination mean?','Altitude is height above the Moon: 50–200 km here. Higher altitude increases orbital period and reduces modeled mapping detail above 100 km. Inclination tilts the orbital plane; near 90° supports polar coverage. The Moon orbit is circular and schematic, not a full trajectory prediction.','Altitude হলো চাঁদের ওপর উচ্চতা। বেশি হলে একবার ঘুরতে সময় বাড়ে, ১০০ km-এর ওপরে detail কমে। Inclination হলো orbit-এর ঢাল; মেরু দেখার জন্য প্রায় ৯০° নিন।','orbit altitude inclination period speed polar radius gm gravity কক্ষপথ উচ্চতা মেরু'],
 ['custom','What can I customize?','Choose seven subsystem classes, fuel, altitude, inclination, solar array size, battery size, instrument duty, Earth–Moon distance scenario, mission name and spacecraft color. Array and battery sizing change mass and cost. Duty changes science, power and data. Cosmetic choices do not change scores.','৭ ধরনের subsystem, fuel, orbit, solar array, battery size, instrument duty, দূরত্ব, নাম ও রং বদলাতে পারেন। Array/battery বড় করলে ওজন ও খরচ বাড়ে। শুধু নাম-রং score বদলায় না।','custom customize customization options change name colour color duty design কাস্টম নাম রং বদল'],
 ['distance','How does NASA distance data affect the game?','Choose NASA mean perigee (363,300 km), reference semimajor axis (384,400 km), or mean apogee (405,500 km). An educational inverse-square rule scales link throughput; distance / speed of light gives one-way signal delay. These are fixed scenarios, not today’s Moon position. Delay is displayed; commands are not delayed.','NASA-র তিনটি দূরত্ব বেছে নিতে পারেন। দূরে হলে এই সরল মডেলে ডেটা পাঠানোর হার কমে। Signal delay দেখানো হয়, command-এ delay দেওয়া হয় না। এগুলো আজকের অবস্থান নয়।','distance perigee apogee delay latency earth moon range দূরত্ব'],
 ['nasa','Which NASA data is actually used?','NASA/JPL Moon radius 1,737.4 km and GM 4,902.800 km³/s² drive orbital period and speed. NASA irradiance 1,361 W/m² drives array sizing. NASA Earth–Moon distance values drive educational link scaling and displayed delay. Open NASA data to inspect the snapshot and sources. No live telemetry or LRO terrain raster is loaded.','JPL-এর radius ও GM দিয়ে orbit, NASA-র irradiance দিয়ে solar panel, এবং চাঁদের দূরত্ব দিয়ে link হিসাব হয়। NASA data-তে সূত্র ও সংখ্যা দেখুন। Live telemetry বা LRO terrain map নেই।','nasa source dataset real authentic reference jpl facts তথ্য সূত্র আসল'],
 ['assumptions','Which values are game assumptions?','Hardware specifications, credits, science units, 28% cell efficiency, 85% operating derating, fixed 35-minute shadow, 25-minute contact, capture requirements and link degradation are educational assumptions. NASA supplies selected environmental data and engineering references, not a certification of this game.','Hardware, credit, score, ২৮% cell efficiency, ৮৫% operating factor, shadow/contact-এর সময় ও crisis-এর নিয়ম শিক্ষামূলক অনুমান। NASA এই গেমের অনুমোদন দেয়নি।','assumption accuracy realistic certified approved simplified model অনুমান বাস্তব নির্ভুল'],
 ['report','Why did my mission fail?','Read the causal debrief: hardware choice → resource limit → event → your response → result. Compare one changed variable at a time, using the same operating commands. Costs alone do not measure success; only useful returned observations count.','Result-এর causal debrief দেখুন: part → সীমাবদ্ধতা → বিপদ → সিদ্ধান্ত → ফল। একই command রেখে একবারে একটি পরিবর্তন করে তুলনা করুন।','fail failed result debrief report lost incomplete why consequence ফল ব্যর্থ কেন'],
 ['save','How do saving and offline play work?','Your design, preferences and completed runs are saved in this browser. Refreshing ends an unfinished flight; use Download read-only report for JSON results. The standalone HTML runs offline without an account or API key. Different browsers do not share local saves. Clearing browser storage removes them.','Design ও finished run এই browser-এ save হয়। Refresh করলে অসমাপ্ত flight হারাবে। Export mission দিয়ে report রাখুন। Standalone HTML offline চলে; অন্য browser-এ save পাওয়া যাবে না।','save export download offline internet refresh reset history সেভ অফলাইন'],
 ['time','How does time work?','Launch, transfer and capture are compressed game stages. The 240-minute campaign starts after capture. +5 min advances at most five simulated minutes and stops for a crisis. Physics uses intervals of at most one minute, split at contact and shadow boundaries. Pause freezes the mission; speed controls change playback, not physics.','Launch ও transfer সংক্ষিপ্ত। Capture-এর পর ২৪০ মিনিটের clock শুরু। +5 min বিপদে থামে। Pause দিলে মিশন থামে; speed শুধু দেখার গতি বদলায়, ফল নয়।','time minute duration clock speed pause fast event সময় মিনিট'],
 ['robust','What is the robustness index?','It is the fraction of 200 seeded simulations meeting this game objective when solar output, link, engine impulse and pointing vary within stated assumptions, with one fixed recovery policy. It is not a real mission success probability or competition-winning chance.','নির্দিষ্ট variation দিয়ে ২০০ simulation-এর কতগুলো লক্ষ্য পূরণ করে তার হার। এটা বাস্তব মিশনের বা competition জেতার সম্ভাবনা নয়।','robust probability chance uncertainty winning selection জেতার চান্স সম্ভাবনা'],
 ['team','How can our six members play together?','Use one device and rotate six roles: mission lead, spacecraft designer, power engineer, communications planner, flight controller and science analyst. Discuss crisis choices together. This version is a single-player local simulation, not network multiplayer. Built for Kemon Dilam Bondhura.','এক device-এ ছয়টি দায়িত্ব ভাগ করুন: mission lead, designer, power, communications, flight control ও science analyst। সিদ্ধান্ত একসাথে নিন। Online multiplayer নেই।','team member multiplayer bondhura project trajectiq দল সদস্য'],
 ['camera','How do I control the 3D view?','Drag sideways to rotate; swipe vertically to scroll the page. Focus the scene before using the wheel to zoom, or use arrow keys and + / − when the scene is focused. R resets the camera. Click a part or the labeled subsystem buttons to inspect it. If WebGL is unavailable, the 2D fallback keeps all gameplay controls available.','পাশে Drag করে ঘোরান; ওপর-নিচে swipe দিয়ে page scroll করুন। Scene focus করে wheel দিয়ে zoom করুন। Arrow ও + / − কাজ করে। R camera reset করে। 3D না চললেও নিচের button দিয়ে খেলা যায়।','camera rotate zoom animation 3d graphics view drag ক্যামেরা ঘোরাব'],
 ['help','What can the assistant answer?','I explain this project, its controls, subsystem choices, current margins, crises, NASA data, equations and results. I can run what-if experiments, compare crisis responses, review designs and remember the last topic. I use local knowledge, rules and the simulation engine, not a live generative AI service. If the question is outside my verified knowledge, I say I cannot answer it.','আমি এই project, controls, part, বর্তমান margin, crisis, NASA data ও result বুঝিয়ে দিই। Local knowledge ব্যবহার করি; live generative AI নই। জানা না থাকলে বলি উত্তর দিতে পারছি না।','assistant help support know answer mentor assistance সহকারী সাহায্য']
];
for(const [key,title,role] of CATEGORIES){
 const en=`${title}: ${role}. `+({bus:'The bus is the spacecraft platform: it provides basic power-consuming systems, pointing and recorder compatibility.',payload:'The payload makes observations. More detail needs more power, data capacity and precise pointing.',power:'Panels generate electricity in sunlight; batteries store energy for shadow. Bigger kits add mass and cost.',propulsion:'The thruster uses propellant to change velocity. Specific impulse (seconds) describes propellant efficiency.',comms:'The antenna sends observations to Earth during contact. A stronger link uses more power.',storage:'The recorder holds observations before downlink. Expanded storage needs a compatible spacecraft bus.',launch:'The provider delivers Earth escape in this game. Its injected-mass limit includes hardware and fuel.'}[key]);
 const bn=({bus:'Bus হলো spacecraft-এর মূল platform; pointing ও storage compatibility নির্ধারণ করে।',payload:'Payload বা camera ছবি ও তথ্য সংগ্রহ করে। বেশি detail-এর জন্য বেশি power ও data লাগে।',power:'Solar panel রোদে বিদ্যুৎ দেয়; battery ছায়ার জন্য শক্তি জমায়।',propulsion:'Thruster fuel ব্যবহার করে গতি বদলায়। Isp বেশি হলে একই fuel দিয়ে বেশি কাজ হয়।',comms:'Antenna contact window-তে বিজ্ঞানীদের কাছে ডেটা পাঠায়।',storage:'Recorder ডেটা জমিয়ে রাখে। Expanded recorder-এর জন্য উপযুক্ত bus লাগে।',launch:'Launcher পৃথিবী থেকে পাঠায়। Hardware ও fuel মিলিয়ে ওজন তার সীমার মধ্যে চাই।'}[key]);
 HELP_TOPICS.push(['category-'+key,'What is the '+title.toLowerCase()+'?',en,bn,key+' '+title+' '+({bus:'বাস প্ল্যাটফর্ম platform avionics',payload:'instrument camera ক্যামেরা যন্ত্র',power:'kit panel',propulsion:'specific impulse',comms:'antenna অ্যান্টেনা',storage:'recorder',launch:'rocket launcher রকেট'}[key])]);
 for(const c of CATALOG[key]){const details=Object.entries(c).filter(([k,v])=>typeof v==='number').map(([k,v])=>`${k}: ${v}`).join('; ');HELP_TOPICS.push(['part-'+key+'-'+c.id,'Tell me about '+c.name,`${c.note} Base catalog values: ${details}. These are fictional educational specifications, not NASA flight hardware. Array/battery customization can change installed values.`,`${c.name}: ${c.note} মূল catalog: ${details}। এগুলো শিক্ষামূলক মান, NASA spacecraft-এর specification নয়।`,c.name.toLowerCase()]);}
}
HELP_TOPICS.push(['parts','Explain all the components','Bus = spacecraft platform; payload = observing instrument; power = solar panels and battery; propulsion = thruster and fuel; communications = antenna sending data home; storage = recorder holding observations; launch = provider carrying the spacecraft. A good design balances all seven.','Bus হলো মূল platform, payload তথ্য সংগ্রহ করে, power বিদ্যুৎ দেয়, propulsion গতি বদলায়, antenna ডেটা পাঠায়, storage ডেটা জমায়, launcher পাঠিয়ে দেয়। সাতটি অংশ একসাথে কাজ করে।','parts components subsystems hardware all part পার্ট যন্ত্রাংশ সব']);

